import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.DACwFHq9.js";const m=JSON.parse('{"title":"External IDE & AI Bridge","description":"Seamlessly bridge Notely knowledge vaults to external AI coding assistants including VS Code, Cursor, Claude Code, GitHub Copilot, Antigravity, and Windsurf with real-time context synchronization and live MCP server tooling.","frontmatter":{"title":"External IDE & AI Bridge","description":"Seamlessly bridge Notely knowledge vaults to external AI coding assistants including VS Code, Cursor, Claude Code, GitHub Copilot, Antigravity, and Windsurf with real-time context synchronization and live MCP server tooling.","keywords":"ide bridge, vscode, cursor, claude code, github copilot, antigravity, windsurf, mcp, prompt transpilation, dynamic context","category":"AI"},"headers":[],"relativePath":"ai/ide-bridge.md","filePath":"ai/ide-bridge.md","lastUpdated":1791393216000}'),o={name:"ai/ide-bridge.md"};function l(d,e,i,r,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="external-ide-ai-bridge" tabindex="-1">External IDE &amp; AI Bridge <a class="header-anchor" href="#external-ide-ai-bridge" aria-label="Permalink to &quot;External IDE &amp; AI Bridge&quot;">​</a></h1><p>Notely&#39;s <strong>External IDE &amp; AI Bridge</strong> turns any external AI coding assistant—such as <strong>VS Code</strong>, <strong>Cursor</strong>, <strong>Claude Code</strong>, <strong>GitHub Copilot</strong>, <strong>Antigravity</strong>, or <strong>Windsurf</strong>—into an expert assistant that natively understands your Notely workspace.</p><p>Whenever you open your vault outside of Notely (e.g. using <em>Open with VS Code</em> or directly in an external editor), external LLMs immediately receive <strong>vault ontology rules, real-time dynamic context, live MCP server tools, visual diagram manipulation guides, task management capabilities, and prompt workflows</strong>.</p><hr><h2 id="_1-how-it-works-the-multi-layer-bridge-architecture" tabindex="-1">1. How It Works: The Multi-Layer Bridge Architecture <a class="header-anchor" href="#_1-how-it-works-the-multi-layer-bridge-architecture" aria-label="Permalink to &quot;1. How It Works: The Multi-Layer Bridge Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>|                               Notely Engine                                 |</span></span>
<span class="line"><span>|                                                                             |</span></span>
<span class="line"><span>|  [Notes Vault] + [Live MCP Server :3700] + [Document &amp; Audio Extractors]    |</span></span>
<span class="line"><span>|                                     │                                       |</span></span>
<span class="line"><span>|                  Background AI Context Bridge Worker                        |</span></span>
<span class="line"><span>|                                     │                                       |</span></span>
<span class="line"><span>+─────────────────────────────────────┼───────────────────────────────────────+</span></span>
<span class="line"><span>                                      │ Auto-Sync (Debounced 5s)</span></span>
<span class="line"><span>                                      ▼</span></span>
<span class="line"><span>+─────────────────────────────────────────────────────────────────────────────+</span></span>
<span class="line"><span>|                         Generated Workspace Artifacts                       |</span></span>
<span class="line"><span>|                                                                             |</span></span>
<span class="line"><span>|  • .notes-app/ai/instructions.md    (Master conventions, syntax, schemas)  |</span></span>
<span class="line"><span>|  • .notes-app/ai/dynamic-context.md (Live note sitemap, tasks, graph hubs)  |</span></span>
<span class="line"><span>|  • .vscode/mcp.json                 (Live MCP server endpoint &amp; auth)       |</span></span>
<span class="line"><span>|  • .vscode/prompts/*.prompt.md      (Transpiled VS Code slash commands)     |</span></span>
<span class="line"><span>|  • .cursor/rules/notely-*.mdc       (Transpiled Cursor MDC rules)           |</span></span>
<span class="line"><span>|  • AGENTS.md / CLAUDE.md / .cursorrules / .github/copilot-instructions.md   |</span></span>
<span class="line"><span>+─────────────────────────────────────┬───────────────────────────────────────+</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>              ┌───────────────────────┼───────────────────────┐</span></span>
<span class="line"><span>              ▼                       ▼                       ▼</span></span>
<span class="line"><span>      [VS Code / Copilot]         [Cursor AI]         [Claude Code / Agent]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><hr><h2 id="_2-generated-bridge-files-locations" tabindex="-1">2. Generated Bridge Files &amp; Locations <a class="header-anchor" href="#_2-generated-bridge-files-locations" aria-label="Permalink to &quot;2. Generated Bridge Files &amp; Locations&quot;">​</a></h2><p>The background worker automatically generates and maintains the following files in your active workspace:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Target File</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Target Tool</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>.notes-app/ai/instructions.md</code></strong></td><td style="text-align:left;">Master instructions on Wikilinks, Markdown hierarchy, diagrams, tasks, and MCP tools.</td><td style="text-align:left;">All LLMs</td></tr><tr><td style="text-align:left;"><strong><code>.notes-app/ai/dynamic-context.md</code></strong></td><td style="text-align:left;">Real-time workspace sitemap, top knowledge hubs, open tasks, recent activity, and extractions.</td><td style="text-align:left;">All LLMs</td></tr><tr><td style="text-align:left;"><strong><code>.vscode/mcp.json</code></strong></td><td style="text-align:left;">Registers Notely&#39;s local MCP server endpoint and authentication tokens.</td><td style="text-align:left;">VS Code, Copilot, Cursor</td></tr><tr><td style="text-align:left;"><strong><code>.vscode/prompts/</code> &amp; <code>.github/prompts/</code></strong></td><td style="text-align:left;">Transpiles <code>.notes-app/prompts/*.md</code> into executable <code>.prompt.md</code> slash commands.</td><td style="text-align:left;">VS Code Chat, Copilot</td></tr><tr><td style="text-align:left;"><strong><code>.cursor/rules/notely-*.mdc</code></strong></td><td style="text-align:left;">Transpiles prompt workflows into scoped Cursor rules.</td><td style="text-align:left;">Cursor AI</td></tr><tr><td style="text-align:left;"><strong><code>AGENTS.md</code></strong></td><td style="text-align:left;">Root entry point for agentic CLI and AI assistants (Antigravity, Gemini CLI).</td><td style="text-align:left;">Antigravity, CLI Agents</td></tr><tr><td style="text-align:left;"><strong><code>CLAUDE.md</code></strong></td><td style="text-align:left;">Root entry point for Anthropic Claude Code and Claude Desktop.</td><td style="text-align:left;">Claude Code</td></tr><tr><td style="text-align:left;"><strong><code>.cursorrules</code></strong></td><td style="text-align:left;">Root configuration rules for Cursor.</td><td style="text-align:left;">Cursor</td></tr><tr><td style="text-align:left;"><strong><code>.github/copilot-instructions.md</code></strong></td><td style="text-align:left;">Custom instructions for GitHub Copilot Chat.</td><td style="text-align:left;">GitHub Copilot</td></tr></tbody></table><hr><h2 id="_3-automatic-gitignore-isolation" tabindex="-1">3. Automatic <code>.gitignore</code> Isolation <a class="header-anchor" href="#_3-automatic-gitignore-isolation" aria-label="Permalink to &quot;3. Automatic \`.gitignore\` Isolation&quot;">​</a></h2><p>Notely ensures that all machine-specific AI bridge files and local authentication tokens are safely isolated from version control.</p><p>When a workspace is initialized or opened, Notely appends a dedicated, managed block to <code>.gitignore</code>:</p><div class="language-gitignore vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># &gt;&gt;&gt; Notely AI IDE Bridge Managed &gt;&gt;&gt;</span></span>
<span class="line"><span>.notes-app/ai/</span></span>
<span class="line"><span>.vscode/mcp.json</span></span>
<span class="line"><span>.vscode/prompts/</span></span>
<span class="line"><span>.github/prompts/</span></span>
<span class="line"><span>.cursor/rules/notely-*.mdc</span></span>
<span class="line"><span># &lt;&lt;&lt; Notely AI IDE Bridge Managed &lt;&lt;&lt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Independent Git Tracking Toggle</p><p>This section is completely separated from <code># &gt;&gt;&gt; Notes App Managed &gt;&gt;&gt;</code> (<code>.notes-app/</code>). Toggling whether to track or ignore <code>.notes-app/</code> in Git works independently and will never interfere with your AI IDE bridge rules.</p></div><hr><h2 id="_4-visual-diagram-prototyping-capabilities" tabindex="-1">4. Visual Diagram &amp; Prototyping Capabilities <a class="header-anchor" href="#_4-visual-diagram-prototyping-capabilities" aria-label="Permalink to &quot;4. Visual Diagram &amp; Prototyping Capabilities&quot;">​</a></h2><p>External LLMs reading <code>instructions.md</code> are trained on Notely&#39;s 4 visual diagram formats and can create or manipulate them on demand:</p><ol><li><strong>Mermaid Diagrams</strong>: Inline fenced code blocks (<code>\`\`\`mermaid</code>) supporting Flowcharts, Sequence Diagrams, Gantt Charts, Class Diagrams, State Diagrams, ER Models, Mindmaps, and Timelines.</li><li><strong>Excalidraw Whiteboards</strong>: Stored under <code>.notes-app/excali-diagrams/&lt;id&gt;/diagram.excalidraw</code> (JSON shapes) and embedded with <code>![Excalidraw Diagram](.notes-app/excali-diagrams/&lt;id&gt;/diagram.png){data-diagram-id=&quot;&lt;id&gt;&quot;}</code>.</li><li><strong>Draw.io Technical Flowcharts</strong>: Stored under <code>.notes-app/drawio-diagrams/&lt;id&gt;.drawio</code> (mxGraph XML) and embedded with <code>![Draw.io Diagram](.notes-app/drawio-diagrams/&lt;id&gt;.png){data-diagram-id=&quot;&lt;id&gt;&quot;}</code>.</li><li><strong>Wireframe Studio</strong>: Stored under <code>.notes-app/wireframes/&lt;id&gt;.wireframe.json</code> and embedded with <code>![Wireframe Diagram](media/wireframes/&lt;id&gt;.png){data-diagram-id=&quot;&lt;id&gt;&quot;}</code>.</li></ol><hr><h2 id="_5-multimodal-assets-audio-document-extractions" tabindex="-1">5. Multimodal Assets: Audio &amp; Document Extractions <a class="header-anchor" href="#_5-multimodal-assets-audio-document-extractions" aria-label="Permalink to &quot;5. Multimodal Assets: Audio &amp; Document Extractions&quot;">​</a></h2><p>External coding assistants cannot natively read binary files (<code>.pdf</code>, <code>.pptx</code>, <code>.docx</code>, <code>.mp3</code>, <code>.m4a</code>). Notely solves this by automatically indexing companion text:</p><ul><li><strong>Audio Transcripts</strong>: Speech-to-text transcripts generated by Notely are cataloged in <code>dynamic-context.md</code> (located in <code>media/audio/&lt;name&gt;/transcript.json</code>).</li><li><strong>Document Extractions</strong>: Extracted text from PDFs, slide decks, spreadsheets, and Word documents is cached under <code>.notes-app/cache/extracted/</code> and exposed directly to external assistants and the MCP semantic search engine.</li></ul><hr><h2 id="_6-global-task-management-support" tabindex="-1">6. Global Task Management Support <a class="header-anchor" href="#_6-global-task-management-support" aria-label="Permalink to &quot;6. Global Task Management Support&quot;">​</a></h2><p>External LLMs are instructed on Notely&#39;s task grammar:</p><ul><li><strong>Checkboxes</strong>: <code>- [ ]</code> (open), <code>- [x]</code> (completed), <code>* [ ]</code>, <code>1. [ ]</code>, <code>[ ]</code>.</li><li><strong>Due Dates &amp; Times</strong>: <code>@due(YYYY-MM-DD)</code> or <code>due:YYYY-MM-DD</code>, <code>@sched(YYYY-MM-DD)</code>, <code>@start()</code>, <code>@end()</code>.</li><li><strong>Priorities</strong>: <code>#urgent</code> / <code>#p1</code>, <code>#high</code> / <code>#p2</code>, <code>#medium</code> / <code>#p3</code>, <code>#low</code>.</li><li><strong>Mentions &amp; Context</strong>: <code>@username</code>, <code>#category</code>, <code>[[Person Note]]</code>.</li></ul><p>External assistants can update task checkbox states directly in the Markdown text or call the live MCP tool <code>manage_tasks</code>.</p><hr><h2 id="_7-reusable-prompt-workflows" tabindex="-1">7. Reusable Prompt Workflows <a class="header-anchor" href="#_7-reusable-prompt-workflows" aria-label="Permalink to &quot;7. Reusable Prompt Workflows&quot;">​</a></h2><p>Custom prompts created in Notely (<code>.notes-app/prompts/*.md</code>) or bundled enterprise prompts are automatically transpiled into:</p><ul><li><strong>VS Code Slash Commands</strong> (e.g. <code>/summarize_note</code>, <code>/plan_tasks</code>, <code>/refactor_note</code>, <code>/daily_review</code>, <code>/synthesize_document</code>, <code>/create_diagram</code>, <code>/atomic_split</code>, <code>/codebase_sync</code>, <code>/explore_knowledge_graph</code>)</li><li><strong>Cursor Rules</strong> (e.g. <code>@notely-summarize_note</code>, <code>@notely-plan_tasks</code>)</li></ul><h3 id="built-in-workflow-prompt-library" tabindex="-1">Built-in Workflow Prompt Library: <a class="header-anchor" href="#built-in-workflow-prompt-library" aria-label="Permalink to &quot;Built-in Workflow Prompt Library:&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Prompt Name</th><th style="text-align:left;">Description</th><th style="text-align:left;">Key Arguments</th></tr></thead><tbody><tr><td style="text-align:left;"><code>summarize_note</code></td><td style="text-align:left;">Executive summary, takeaways, and open tasks for any note.</td><td style="text-align:left;"><code>notePath</code>, <code>depth</code></td></tr><tr><td style="text-align:left;"><code>plan_tasks</code></td><td style="text-align:left;">Break down a feature goal into phased actionable checklist tasks.</td><td style="text-align:left;"><code>goal</code>, <code>targetNote</code>, <code>includeDates</code></td></tr><tr><td style="text-align:left;"><code>explore_knowledge_graph</code></td><td style="text-align:left;">Analyze backlinks, conceptual clusters, and build Mermaid relationships.</td><td style="text-align:left;"><code>topicOrNote</code>, <code>maxDepth</code></td></tr><tr><td style="text-align:left;"><code>refactor_note</code></td><td style="text-align:left;">Clean note hierarchy, YAML frontmatter, and convert mentions to wikilinks.</td><td style="text-align:left;"><code>notePath</code></td></tr><tr><td style="text-align:left;"><code>daily_review</code></td><td style="text-align:left;">Briefing of overdue/today tasks and recently modified notes.</td><td style="text-align:left;"><code>filter</code> (<code>today</code>, <code>overdue</code>, <code>all</code>)</td></tr><tr><td style="text-align:left;"><code>synthesize_document</code></td><td style="text-align:left;">Read extracted PDF/PPTX/DOCX or audio transcript and produce a structured study note.</td><td style="text-align:left;"><code>assetPath</code>, <code>targetNote</code></td></tr><tr><td style="text-align:left;"><code>create_diagram</code></td><td style="text-align:left;">Generate a Mermaid flowchart, sequence, class, state, or ER diagram from a note.</td><td style="text-align:left;"><code>notePath</code>, <code>diagramType</code></td></tr><tr><td style="text-align:left;"><code>atomic_split</code></td><td style="text-align:left;">Split a monolithic document into atomic notes and create an index MOC note.</td><td style="text-align:left;"><code>sourceNote</code>, <code>outputFolder</code></td></tr><tr><td style="text-align:left;"><code>codebase_sync</code></td><td style="text-align:left;">Cross-reference attached Git repository code against notes for documentation gaps.</td><td style="text-align:left;"><code>repoName</code></td></tr></tbody></table><hr><h2 id="_8-live-mcp-server-integration" tabindex="-1">8. Live MCP Server Integration <a class="header-anchor" href="#_8-live-mcp-server-integration" aria-label="Permalink to &quot;8. Live MCP Server Integration&quot;">​</a></h2><p>When your external IDE is configured with Notely&#39;s MCP server (<code>.vscode/mcp.json</code>), external agents gain access to 7 high-performance tools:</p><table tabindex="0"><thead><tr><th style="text-align:left;">MCP Tool</th><th style="text-align:left;">Capability</th></tr></thead><tbody><tr><td style="text-align:left;"><code>read_note</code></td><td style="text-align:left;">360° note inspector (clean text, headings, frontmatter, diagrams, tasks, backlinks, git commits).</td></tr><tr><td style="text-align:left;"><code>edit_note</code></td><td style="text-align:left;">Safe, atomic note modifier with diff preview and dry-run safety.</td></tr><tr><td style="text-align:left;"><code>manage_diagrams</code></td><td style="text-align:left;">Create, update, read, and list Mermaid, Excalidraw, and Draw.io visual diagrams.</td></tr><tr><td style="text-align:left;"><code>manage_tasks</code></td><td style="text-align:left;">Query, aggregate, toggle, and filter tasks across the entire vault.</td></tr><tr><td style="text-align:left;"><code>search</code></td><td style="text-align:left;">Hybrid full-text and semantic vector search across notes and extracted binary documents.</td></tr><tr><td style="text-align:left;"><code>get_knowledge_graph</code></td><td style="text-align:left;">Explore node degree centrality, backlinks, and conceptual clusters.</td></tr><tr><td style="text-align:left;"><code>workspace_overview</code></td><td style="text-align:left;">High-level vault health, statistics, and recent activity feed.</td></tr></tbody></table>`,39)])])}const u=t(o,[["render",l]]);export{m as __pageData,u as default};
